$$
 egin{aligned}{f}^{′}(x) & ={({x}^{2})}^{′}\cdot \operatorname{coth}⁡x+{x}^{2}\cdot {(\operatorname{coth}⁡x)}^{′} \  & =2x\cdot \operatorname{coth}⁡x+{x}^{2}\cdot (-{csch}^{2}⁡x) \  & =x(2\operatorname{coth}⁡x-x{csch}^{2}⁡x)\end{aligned}
